// Generates src/terminal/terminal-html.generated.ts: one self-contained HTML string with xterm.js,
// its stylesheet and the page script inlined, so the terminal WebView needs no network and no
// bundler support for .html or .css assets. Run by `npm run check` and `npm start`.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const require = createRequire(import.meta.url);
const xtermDir = path.dirname(require.resolve("@xterm/xterm/package.json"));

const script = readFileSync(path.join(xtermDir, "lib/xterm.js"), "utf8")
  .replace(/\/\/# sourceMappingURL=.*$/m, "")
  // A literal closing tag inside an inline script would end it early.
  .replaceAll("</script", "<\\/script");
const css = readFileSync(path.join(xtermDir, "css/xterm.css"), "utf8");
const page = readFileSync(path.join(root, "scripts/terminal-page.js"), "utf8");

const html = `<!doctype html><html><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<style>${css}
html,body{margin:0;padding:0;overflow:auto;-webkit-text-size-adjust:none;-webkit-user-select:none;user-select:none;-webkit-touch-callout:none}
#term{display:inline-block;min-width:100%}
.xterm-viewport{overflow:hidden !important}
</style></head><body><div id="term"></div>
<script>${script}</script>
<script>${page}</script></body></html>`;

const out = path.join(root, "src/terminal/terminal-html.generated.ts");
mkdirSync(path.dirname(out), { recursive: true });
writeFileSync(
  out,
  `// Generated by scripts/build-terminal-html.mjs from @xterm/xterm. Do not edit.\nexport const TERMINAL_HTML: string = ${JSON.stringify(html)};\n`,
);
console.log(`terminal html: ${(html.length / 1024).toFixed(0)} KiB -> ${path.relative(root, out)}`);
